<link rel="stylesheet" href="/auth-assets/design-tokens.css">
<style>
@font-face{font-family:'Google Sans';font-style:normal;font-weight:500;font-display:swap;src:url('/auth-assets/google-sans-latin.woff2') format('woff2')}
*{box-sizing:border-box}body{overflow-wrap:anywhere;font:1rem/1.5 var(--gen-font-account);background:var(--gen-background);color:var(--gen-text);margin:0;padding:var(--gen-space-lg)}main{max-width:440px;margin:3vh auto;background:var(--gen-surface);padding:var(--gen-space-xxl);border-radius:var(--gen-radius-panel)}h1{font-size:1.6rem;margin-top:0}h2{font-size:1.2rem}label,input,button{display:block;width:100%}input,button{font:inherit;padding:var(--gen-space-md);border:1px solid var(--gen-web-field-border);border-radius:var(--gen-radius-control);margin:8px 0 16px;min-height:48px;min-width:0}button{background:var(--gen-accent);color:var(--gen-on-accent);border:0;cursor:pointer}button:disabled{background:var(--gen-web-disabled-surface);color:var(--gen-web-disabled-text);cursor:default}a{color:var(--gen-accent)}small{display:block}p[role=alert]{padding:var(--gen-space-md);background:var(--gen-web-notice-surface);border-left:4px solid var(--gen-accent)}hr{border:0;border-top:1px solid var(--gen-line);margin:24px 0}:focus-visible{outline:3px solid var(--gen-web-focus);outline-offset:3px}
.account-modes{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;margin:20px 0}.account-modes a{min-width:0;display:flex;align-items:center;justify-content:center;min-height:48px;padding:10px 6px;text-align:center;border:1px solid var(--gen-accent);border-radius:var(--gen-radius-control);text-decoration:none;font-weight:600}.account-modes a[aria-current=page]{background:var(--gen-accent);color:var(--gen-on-accent)}
.provider{display:flex;align-items:center;gap:12px;border-radius:8px;margin:12px 0;min-height:48px}.provider span:last-child{min-width:0;flex:1;text-align:center}.provider:disabled{opacity:.55;cursor:not-allowed}.provider-google,.provider-google:disabled{background:#fff;color:#1f1f1f;border:1px solid #747775;font:500 .875rem/1.4 'Google Sans',Arial,sans-serif}.provider-apple,.provider-apple:disabled{background:#000;color:#fff;font-weight:500}.provider-mark{display:block;flex:0 0 20px;width:20px;height:20px;overflow:hidden;position:relative}.provider-mark img{display:block;position:absolute;max-width:none}.provider-google img{width:40px;height:40px;left:-10px;top:-10px}.provider-apple{padding:0 12px 0 0;gap:0}.provider-apple .provider-mark{flex-basis:44px;width:44px;height:44px}.provider-apple img{width:44px;height:44px;left:0;top:0}.provider-note{font-size:.875rem;color:var(--gen-secondary)}summary{cursor:pointer;min-height:44px;padding:10px 0}
</style>
<style>.consent{display:flex;align-items:flex-start;gap:10px;margin:12px 0;font-size:.9rem;min-height:44px}.consent input{flex:0 0 20px;width:20px;min-height:20px;margin:2px 0;padding:0}.consent span{min-width:0}</style>
